#include <zephyr/kernel.h>
#include <zephyr/lib/hash_map.h>

/*
 * This is a basic open-addressing hash map implementation with linear probing.
 * It supports deletion by marking entries as HASH_MAP_ENTRY_DELETED.
 */

void hash_map_init(struct hash_map *map,
                   struct hash_map_entry *entries, uint32_t capacity,
                   hash_map_hash_func_t hash_func,
                   hash_map_cmp_func_t cmp_func)
{
    __ASSERT_NO_MSG(map != NULL);
    __ASSERT_NO_MSG(entries != NULL);
    __ASSERT_NO_MSG(capacity > 0); /* Capacity must be greater than 0 to avoid modulo by zero */
    __ASSERT_NO_MSG(hash_func != NULL);
    __ASSERT_NO_MSG(cmp_func != NULL);

    map->entries = entries;
    map->capacity = capacity;
    map->hash_func = hash_func;
    map->cmp_func = cmp_func;
    map->size = 0;

    for (uint32_t i = 0; i < capacity; ++i) {
        map->entries[i].state = HASH_MAP_ENTRY_EMPTY;
        /* Optionally clear key/value pointers, though not strictly necessary for EMPTY state */
        /* map->entries[i].key = NULL; */
        /* map->entries[i].value = NULL; */
    }
}

bool hash_map_insert(struct hash_map *map, const void *key, void *value)
{
    __ASSERT_NO_MSG(map != NULL);
    __ASSERT_NO_MSG(key != NULL); /* Keys should generally not be NULL */

    if (map->size == map->capacity) {
        return false; /* Map is full */
    }

    uint32_t hash = map->hash_func(key);
    uint32_t idx = hash % map->capacity;

    for (uint32_t i = 0; i < map->capacity; ++i) {
        struct hash_map_entry *entry = &map->entries[(idx + i) % map->capacity];

        if (entry->state == HASH_MAP_ENTRY_OCCUPIED) {
            if (map->cmp_func(key, entry->key)) {
                /* Key already exists, update value */
                entry->value = value;
                return true;
            }
        } else { /* HASH_MAP_ENTRY_EMPTY or HASH_MAP_ENTRY_DELETED */
            entry->key = key;
            entry->value = value;
            entry->state = HASH_MAP_ENTRY_OCCUPIED;
            map->size++;
            return true;
        }
    }
    return false; /* Should not be reached if map->size < map->capacity */
}

bool hash_map_get(struct hash_map *map, const void *key, void **value)
{
    __ASSERT_NO_MSG(map != NULL);
    __ASSERT_NO_MSG(key != NULL); /* Keys should generally not be NULL */

    uint32_t hash = map->hash_func(key);
    uint32_t idx = hash % map->capacity;

    for (uint32_t i = 0; i < map->capacity; ++i) {
        struct hash_map_entry *entry = &map->entries[(idx + i) % map->capacity];

        if (entry->state == HASH_MAP_ENTRY_EMPTY) {
            return false; /* Key not found */
        }

        if (entry->state == HASH_MAP_ENTRY_OCCUPIED && map->cmp_func(key, entry->key)) {
            if (value != NULL) {
                *value = entry->value;
            }
            return true; /* Key found */
        }
        /* If state is HASH_MAP_ENTRY_DELETED, continue probing */
    }

    return false; /* Table full, key not found */
}

bool hash_map_remove(struct hash_map *map, const void *key, void **value)
{
    __ASSERT_NO_MSG(map != NULL);
    __ASSERT_NO_MSG(key != NULL); /* Keys should generally not be NULL */

    uint32_t hash = map->hash_func(key);
    uint32_t idx = hash % map->capacity;

    for (uint32_t i = 0; i < map->capacity; ++i) {
        struct hash_map_entry *entry = &map->entries[(idx + i) % map->capacity];

        if (entry->state == HASH_MAP_ENTRY_EMPTY) {
            return false; /* Key not found */
        }

        if (entry->state == HASH_MAP_ENTRY_OCCUPIED && map->cmp_func(key, entry->key)) {
            if (value != NULL) {
                *value = entry->value;
            }
            entry->state = HASH_MAP_ENTRY_DELETED;
            map->size--;
            return true; /* Key found and removed */
        }
        /* If state is HASH_MAP_ENTRY_DELETED, continue probing */
    }

    return false; /* Table full, key not found */
}

void hash_map_clear(struct hash_map *map, hash_map_clear_cb_t cb)
{
    __ASSERT_NO_MSG(map != NULL);

    for (uint32_t i = 0; i < map->capacity; ++i) {
        struct hash_map_entry *entry = &map->entries[i];
        if (entry->state == HASH_MAP_ENTRY_OCCUPIED) {
            if (cb != NULL) {
                cb(entry->key, entry->value);
            }
            entry->state = HASH_MAP_ENTRY_EMPTY;
            /* Optionally clear key/value pointers */
            /* entry->key = NULL; */
            /* entry->value = NULL; */
        } else if (entry->state == HASH_MAP_ENTRY_DELETED) {
            entry->state = HASH_MAP_ENTRY_EMPTY;
            /* Optionally clear key/value pointers */
            /* entry->key = NULL; */
            /* entry->value = NULL; */
        }
    }
    map->size = 0;
}

void hash_map_foreach(struct hash_map *map, hash_map_foreach_cb_t cb)
{
    __ASSERT_NO_MSG(map != NULL);
    __ASSERT_NO_MSG(cb != NULL); /* Callback must be provided for foreach */

    for (uint32_t i = 0; i < map->capacity; ++i) {
        struct hash_map_entry *entry = &map->entries[i];
        if (entry->state == HASH_MAP_ENTRY_OCCUPIED) {
            cb(entry->key, entry->value);
        }
    }
}

uint32_t hash_map_size(const struct hash_map *map)
{
    __ASSERT_NO_MSG(map != NULL);
    return map->size;
}

uint32_t hash_map_capacity(const struct hash_map *map)
{
    __ASSERT_NO_MSG(map != NULL);
    return map->capacity;
}
